# ---------------------------------------------------------------- docx

def shade(cell, hexcolor):
    tcPr = cell._tc.get_or_add_tcPr()
    el = OxmlElement('w:shd'); el.set(qn('w:val'), 'clear')
    el.set(qn('w:color'), 'auto'); el.set(qn('w:fill'), hexcolor)
    tcPr.append(el)

def setfont(run, size=10.5, bold=False, color=INK):
    run.font.name = FONT; run.font.size = Pt(size); run.bold = bold; run.font.color.rgb = color
    rPr = run._element.get_or_add_rPr()
    rf = rPr.find(qn('w:rFonts'))
    if rf is None:
        rf = OxmlElement('w:rFonts'); rPr.append(rf)
    for a in ('w:ascii','w:hAnsi','w:cs','w:eastAsia'):
        rf.set(qn(a), FONT)
    sz = OxmlElement('w:szCs'); sz.set(qn('w:val'), str(int(size*2))); rPr.append(sz)

def para(doc, text, size=10.5, bold=False, color=INK, space_after=5, align=None, indent=None):
    p = doc.add_paragraph()
    if align is not None: p.alignment = align
    if indent is not None: p.paragraph_format.left_indent = Cm(indent)
    p.paragraph_format.space_after = Pt(space_after)
    p.paragraph_format.space_before = Pt(0)
    setfont(p.add_run(text), size, bold, color)
    return p

def heading(doc, text, level=1):
    sizes = {0: 20, 1: 14.5, 2: 12}
    cols  = {0: NAVY, 1: NAVY, 2: TEAL}
    p = doc.add_paragraph()
    p.paragraph_format.space_before = Pt(14 if level else 0)
    p.paragraph_format.space_after  = Pt(5)
    p.paragraph_format.keep_with_next = True
    setfont(p.add_run(text), sizes[level], True, cols[level])
    return p

def table(doc, headers, rows, widths):
    t = doc.add_table(rows=1, cols=len(headers))
    t.style = 'Table Grid'; t.alignment = WD_TABLE_ALIGNMENT.LEFT
    for i, h in enumerate(headers):
        c = t.rows[0].cells[i]; c.text = ''
        shade(c, 'E7EEF1')
        setfont(c.paragraphs[0].add_run(h), 10, True, NAVY)
        c.width = Cm(widths[i])
    for r in rows:
        cells = t.add_row().cells
        for i, v in enumerate(r):
            cells[i].text = ''
            cells[i].width = Cm(widths[i])
            setfont(cells[i].paragraphs[0].add_run(v), 9.5, i == 0, INK if i else NAVY)
    return t

def build_docx(key, r, outdir):
    doc = Document()
    sec = doc.sections[0]
    sec.left_margin = sec.right_margin = Cm(2.0)
    sec.top_margin = sec.bottom_margin = Cm(1.8)
    st = doc.styles['Normal']; st.font.name = FONT; st.font.size = Pt(10.5)
    st.element.rPr.rFonts.set(qn('w:cs'), FONT)

    para(doc, 'ATOM NURSERY', 10, True, TEAL, 2)
    heading(doc, r['title'], 0)
    para(doc, r['who'], 11, False, MUTED, 10)

    t = table(doc, ['หัวข้อ', 'รายละเอียด'], [
        ['เมนูที่เห็น', r['nav']],
        ['อายุการเข้าสู่ระบบ', r['session']],
        ['อุปกรณ์', 'มือถือเป็นหลัก · ใช้บนคอมพิวเตอร์ได้'],
        ['เวอร์ชันคู่มือ', 'จัดทำจากระบบเวอร์ชัน 384 (15 กันยายน 2569)'],
    ], [4.0, 12.5])

    heading(doc, '1 · การเข้าสู่ระบบ')
    for h, d in COMMON_LOGIN:
        para(doc, '▸ ' + h, 10.5, True, TEAL, 1)
        para(doc, d, 10, False, INK, 6, indent=0.55)

    heading(doc, '2 · หน้าจอทั้งหมด และสิ่งที่ทำได้')
    for i, (name, purpose, actions) in enumerate(r['screens'], 1):
        heading(doc, f'2.{i}  {name}', 2)
        if purpose: para(doc, purpose, 10, False, MUTED, 5)
        for a, d in actions:
            p = doc.add_paragraph(); p.paragraph_format.left_indent = Cm(0.55)
            p.paragraph_format.space_after = Pt(3)
            setfont(p.add_run('• ' + a), 10, True, INK)
            if d: setfont(p.add_run('  —  ' + d), 10, False, MUTED)

    heading(doc, '3 · กฎและเงื่อนไขที่ต้องรู้')
    for i, (h, d) in enumerate(r['rules'], 1):
        para(doc, f'{i}.  {h}', 10.5, True, NAVY, 1)
        para(doc, d, 10, False, INK, 7, indent=0.6)

    heading(doc, '4 · ข้อความที่ระบบอาจปฏิเสธ และวิธีแก้')
    para(doc, 'ข้อความเหล่านี้ไม่ใช่ความผิดพลาดของระบบ แต่เป็นกฎที่ระบบบังคับไว้', 10, False, MUTED, 6)
    table(doc, ['ข้อความที่เห็น', 'เกิดขึ้นเมื่อ', 'ต้องทำอย่างไร'],
          [list(x) for x in r['refusals']], [5.6, 5.4, 5.5])

    heading(doc, '5 · สิ่งที่บทบาทนี้ทำไม่ได้')
    for c in r['cannot']:
        p = doc.add_paragraph(); p.paragraph_format.left_indent = Cm(0.55)
        p.paragraph_format.space_after = Pt(3)
        setfont(p.add_run('✕  '), 10, True, CLAY)
        setfont(p.add_run(c), 10, False, INK)

    heading(doc, '6 · หมายเหตุการจัดทำ')
    para(doc, 'คู่มือฉบับนี้สร้างจากการอ่านโค้ดและชุดทดสอบของระบบจริง ไม่ใช่จากความจำ '
              'ก่อนนำไปใช้เป็นข้อกำหนดของระบบใหม่ ขอให้ผู้ใช้งานจริงของบทบาทนี้อ่านและยืนยันว่าตรงกับการทำงานประจำวัน '
              'หากพบข้อใดไม่ตรง ให้ถือว่าคู่มือผิดและแจ้งกลับเพื่อแก้ไข — เพราะระบบใหม่จะถูกสร้างตามคู่มือนี้',
              9.5, False, MUTED, 4)

    path = os.path.join(outdir, r['file'] + '.docx')
    doc.save(path)
    return path

# ---------------------------------------------------------------- markdown

def build_md(key, r, outdir):
    L = []
    A = L.append
    A(f"# {r['title']}\n")
    A(f"> {r['who']}\n")
    A('| | |\n|---|---|')
    A(f"| เมนูที่เห็น | {r['nav']} |")
    A(f"| อายุการเข้าสู่ระบบ | {r['session']} |")
    A("| เวอร์ชัน | จัดทำจากระบบเวอร์ชัน 384 (2026-09-15) |\n")
    A('## 1 · การเข้าสู่ระบบ\n')
    for h, d in COMMON_LOGIN:
        A(f"**{h}** — {d}\n")
    A('## 2 · หน้าจอทั้งหมด และสิ่งที่ทำได้\n')
    for i, (name, purpose, actions) in enumerate(r['screens'], 1):
        A(f"### 2.{i} {name}\n")
        if purpose: A(f"_{purpose}_\n")
        for a, d in actions:
            A(f"- **{a}**" + (f" — {d}" if d else ""))
        A('')
    A('## 3 · กฎและเงื่อนไขที่ต้องรู้\n')
    for i, (h, d) in enumerate(r['rules'], 1):
        A(f"{i}. **{h}**  \n   {d}\n")
    A('## 4 · ข้อความที่ระบบอาจปฏิเสธ และวิธีแก้\n')
    A('| ข้อความที่เห็น | เกิดขึ้นเมื่อ | ต้องทำอย่างไร |\n|---|---|---|')
    for a, b, c in r['refusals']:
        A(f"| {a} | {b} | {c} |")
    A('')
    A('## 5 · สิ่งที่บทบาทนี้ทำไม่ได้\n')
    for c in r['cannot']:
        A(f"- ✕ {c}")
    A('')
    A('## 6 · หมายเหตุการจัดทำ\n')
    A('สร้างจากการอ่านโค้ดและชุดทดสอบของระบบจริง ไม่ใช่จากความจำ · '
      'ก่อนใช้เป็นข้อกำหนดของระบบใหม่ ขอให้ผู้ใช้งานจริงของบทบาทนี้อ่านและยืนยัน — '
      'หากพบข้อใดไม่ตรง ให้ถือว่าคู่มือผิด เพราะระบบใหม่จะถูกสร้างตามคู่มือนี้\n')
    path = os.path.join(outdir, key + '.md')
    with io.open(path, 'w', encoding='utf-8') as f:
        f.write('\n'.join(L))
    return path

# ---------------------------------------------------------------- run

if __name__ == '__main__':
    os.makedirs('dist', exist_ok=True)
    os.makedirs(os.path.join('docs', 'spec', 'roles'), exist_ok=True)
    for key, r in ROLES.items():
        d = build_docx(key, r, 'dist')
        m = build_md(key, r, os.path.join('docs', 'spec', 'roles'))
        print('written:', d)
        print('written:', m)
